function showPage(id){
  document.querySelectorAll('[id^="page-"]').forEach(p=>p.classList.add('hidden'));
  document.getElementById('page-hr-dashboard').classList.add('hidden');
  document.getElementById(id).classList.remove('hidden');
  if (id === 'page-daftar') populatePosisiDropdown();
  // Reset overlays
  const blur = document.getElementById('blur-overlay');
  if(blur) blur.classList.remove('active');
  const viol = document.getElementById('violation-popup');
  if(viol) viol.style.display='none';
}

function switchMenu(menu){
  ['dashboard','pipeline','rekap','pelamar','kandidat','sesi','analitik','log','lowongan','monitor','chat','template'].forEach(m=>{
    const panel=document.getElementById('panel-'+m); if(panel){panel.style.cssText='';panel.classList.add('hidden');}
    if(m==='monitor'&&_monitorRefreshInterval){clearInterval(_monitorRefreshInterval);_monitorRefreshInterval=null;stopAllHRRtc();}
    const menuEl=document.getElementById('menu-'+m); if(menuEl) menuEl.classList.remove('active');
  });
  const activePanel = document.getElementById('panel-'+menu);
  if (activePanel) { activePanel.classList.remove('hidden'); activePanel.style.display = 'block'; }
  document.getElementById('menu-'+menu).classList.add('active');
  const titles={dashboard:'Beranda',pipeline:'Pipeline Rekrutmen',rekap:'KPI & Analitik',pelamar:'Data Pelamar',kandidat:'Hasil Kandidat',sesi:'Kelola Sesi',analitik:'Analitik & Laporan',log:'Log Aktivitas',lowongan:'Lowongan & MPP',monitor:'Monitor Live',chat:'Pesan Kandidat',template:'Template Pesan'};
  if(menu==='template') renderTemplatePanel();
  document.getElementById('topbar-title').textContent=titles[menu]||menu;
  if(menu==='pipeline') loadPipeline();
  if(menu==='pelamar') loadPelamar();
  if(menu==='kandidat') loadHasil();
  if(menu==='sesi') loadSesi();
  if(menu==='analitik') loadAnalitik();
  if(menu==='log') loadLog();
  if(menu==='lowongan') loadLowongan();
  if(menu==='monitor') loadMonitor();
  if(menu==='chat') loadChatList();
  if(menu==='rekap'){ const btn=document.querySelector('.kpi-period-btn[data-days="30"]'); if(btn&&!document.querySelector('.kpi-period-btn.active')) btn.click(); else loadRekap(); }
}


