function switchPmTab(tab) {
  ['berkas','psiko','interview','offering'].forEach(t => {
    const pane = document.getElementById('pm-pane-'+t);
    const btn  = document.getElementById('pm-tab-'+t);
    if (pane) pane.classList.toggle('hidden', t !== tab);
    if (btn) {
      btn.style.color = t === tab ? 'var(--primary)' : 'var(--muted)';
      btn.style.borderBottom = t === tab ? '2px solid var(--primary)' : '2px solid transparent';
    }
  });
}

function setRating(btn, key, score) {
  const hidden = document.getElementById(key);
  if (hidden) hidden.value = score;
  // Update all buttons in same group
  const all = document.querySelectorAll(`[data-key="${key}"]`);
  all.forEach(b => {
    const n = parseInt(b.dataset.score);
    b.style.background = n <= score ? 'var(--primary)' : 'var(--card)';
    b.style.color = n <= score ? '#fff' : 'var(--text)';
    b.style.borderColor = n <= score ? 'var(--primary)' : 'var(--border)';
  });
}

function loadRatingsToUI(notes) {
  // notes is the catatan_hr JSON string or plain text
  try {
    const parsed = typeof notes === 'string' && notes.startsWith('{') ? JSON.parse(notes) : null;
    if (!parsed) return;
    if (parsed.ratings) {
      Object.entries(parsed.ratings).forEach(([key, val]) => {
        const btn = document.querySelector(`[data-key="${key}"][data-score="${val}"]`);
        if (btn) setRating(btn, key, val);
      });
    }
    if (parsed.catatan_berkas) document.getElementById('pm-catatan-berkas').value = parsed.catatan_berkas;
    if (parsed.catatan_psiko)  document.getElementById('pm-catatan-psiko').value  = parsed.catatan_psiko;
    if (parsed.catatan_int)    document.getElementById('pm-catatan-interview').value = parsed.catatan_int;
    if (parsed.catatan_off)    document.getElementById('pm-catatan-offering').value = parsed.catatan_off;
    if (parsed.rekomendasi)    { const r=document.getElementById('pm-rekomendasi'); if(r) r.value=parsed.rekomendasi; }
    if (parsed.catatan_umum)   document.getElementById('pm-catatan').value = parsed.catatan_umum;
  } catch(e) {
    // plain text fallback
    const el = document.getElementById('pm-catatan');
    if (el && notes) el.value = notes;
  }
}

function getRatingsFromUI() {
  const ratings = {};
  document.querySelectorAll('[data-key]').forEach(btn => {
    const key = btn.dataset.key;
    const hidden = document.getElementById(key);
    if (hidden && parseInt(hidden.value) > 0) ratings[key] = parseInt(hidden.value);
  });
  return JSON.stringify({
    ratings,
    catatan_berkas: document.getElementById('pm-catatan-berkas')?.value || '',
    catatan_psiko:  document.getElementById('pm-catatan-psiko')?.value  || '',
    catatan_int:    document.getElementById('pm-catatan-interview')?.value || '',
    catatan_off:    document.getElementById('pm-catatan-offering')?.value || '',
    rekomendasi:    document.getElementById('pm-rekomendasi')?.value || '',
    catatan_umum:   document.getElementById('pm-catatan')?.value || ''
  });
}

function toggleDarkMode(){
  const isDark = document.body.classList.toggle('dark');
  localStorage.setItem('crustea-dark', isDark ? '1' : '');
  document.getElementById('dark-toggle').textContent = isDark ? '☀️' : '🌙';
}
// Apply saved dark mode on load
(function(){
  if(localStorage.getItem('crustea-dark')==='1'){
    document.body.classList.add('dark');
    // Button icon set after DOM ready
    document.addEventListener('DOMContentLoaded',()=>{
      const btn=document.getElementById('dark-toggle');
      if(btn) btn.textContent='☀️';
    });
  }
})();

async function sbFetch(path, options = {}) {
  const payload = {
    path,
    method: options.method || 'GET',
    body: options.body ? JSON.parse(options.body) : undefined,
    headers: options.headers || {},
    prefer: options.prefer,
  };
  const res = await fetch('/api/db', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify(payload),
  });
  if (res.status === 204) return null;
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || err.message || `HTTP ${res.status}`);
  }
  const t = await res.text();
  return t ? JSON.parse(t) : null;
}


// ===== CEK STATUS LAMARAN =====
async function cekStatusLamaran(){
  const q=(document.getElementById('cek-input')?.value||'').trim();
  const errEl=document.getElementById('cek-error');
  const hasil=document.getElementById('cek-hasil');
  errEl.style.display='none'; hasil.style.display='none';
  if(!q||!q.includes('@')){errEl.textContent='Masukkan alamat email yang valid.';errEl.style.display='block';return;}
  const filter='email=eq.'+encodeURIComponent(q);
  try{
    const data=await sbFetch('pelamar?'+filter+'&select=id,nama,posisi_dilamar,jenis_rekrutmen,status,status_akhir,dibuat_at,tgl_seleksi_berkas,result_seleksi_berkas,tgl_psikotest,result_psikotest,tgl_interview,result_interview,tgl_offering,result_offering&limit=3');
    if(!data||!data.length){errEl.textContent='Data tidak ditemukan. Pastikan email sesuai yang Anda gunakan saat mendaftar.';errEl.style.display='block';return;}
    const tgl=d=>d?new Date(d).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):null;
    const badge=r=>{if(!r||r==='pending') return '<span style="background:#e9ecef;color:#6c757d;padding:2px 8px;border-radius:10px;font-size:.8em">Menunggu</span>';if(r==='pass'||r==='accept') return '<span style="background:#d4edda;color:#155724;padding:2px 8px;border-radius:10px;font-size:.8em">✅ Lolos</span>';return '<span style="background:#f8d7da;color:#721c24;padding:2px 8px;border-radius:10px;font-size:.8em">❌ Tidak Lolos</span>';};
    hasil.style.display='block';
    hasil.innerHTML=data.map(p=>{
      const stMap={menunggu:{ic:'⏳',label:'Menunggu Review',bg:'#fff3cd',col:'#856404',msg:'Lamaran Anda sedang dalam antrian review tim HR. Kami akan menghubungi Anda segera.'},disetujui:{ic:'✅',label:'Dalam Proses Seleksi',bg:'#d4edda',col:'#155724',msg:'Lamaran Anda disetujui. Cek email Anda untuk kode akses tes.'},ditolak:{ic:'❌',label:'Belum Dapat Dilanjutkan',bg:'#f8d7da',col:'#721c24',msg:'Pada kesempatan ini kami belum dapat melanjutkan lamaran Anda. Terima kasih atas minat Anda.'}}[p.status]||{ic:'🔄',label:p.status,bg:'#e9ecef',col:'#495057',msg:''};
      const timeline=p.status==='disetujui'?'<div style="margin-top:14px;border-top:1px solid rgba(0,0,0,.08);padding-top:12px"><div style="font-size:.78em;font-weight:700;color:#555;margin-bottom:10px;text-transform:uppercase;letter-spacing:.5px">Progres Seleksi</div><div style="display:grid;gap:6px">'+[['📄 Seleksi Berkas',p.tgl_seleksi_berkas,p.result_seleksi_berkas],['🧠 Psikotest',p.tgl_psikotest,p.result_psikotest],['🎙️ Interview',p.tgl_interview,p.result_interview],['🤝 Offering',p.tgl_offering,p.result_offering]].map(function(x){var lbl=x[0],t=x[1],r=x[2];return '<div style="display:flex;justify-content:space-between;align-items:center;font-size:.82em;padding:5px 0;border-bottom:1px solid rgba(0,0,0,.05)"><span>'+lbl+(t?' <span style=\'color:#aaa;font-size:.85em\'>&middot; '+tgl(t)+'</span>':'')+'</span>'+badge(r)+'</div>';}).join('')+'</div></div>':'';
      const statusFinal = p.status === 'ditolak' || p.status_akhir === 'hired' || p.status_akhir === 'withdrawn';
      const chatInputHtml = statusFinal
        ? `<div style="background:#f8f9fa;border:1px solid #e2e8f0;border-radius:8px;padding:10px 14px;font-size:.8em;color:#718096;text-align:center">
            🔒 Sesi chat telah ditutup karena proses seleksi sudah selesai.
           </div>`
        : `<div style="display:flex;gap:8px">
            <input type="text" id="kandidat-chat-input-${p.id}" placeholder="Balas pesan HR..." style="flex:1;border:1px solid #ddd;border-radius:8px;padding:7px 12px;font-size:.84em" onkeydown="if(event.key==='Enter')kirimPesanKandidat('${p.id}')">
            <button onclick="kirimPesanKandidat('${p.id}')" style="background:#0d6e7e;color:#fff;border:none;border-radius:8px;padding:7px 14px;font-size:.84em;cursor:pointer;font-weight:600">Kirim</button>
           </div>`;

      const chatSection = p.id ? `
        <div style="margin-top:14px;border-top:1px solid rgba(0,0,0,.08);padding-top:12px">
          <div style="font-size:.78em;font-weight:700;color:#555;margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px">
            💬 Pesan dari HR ${statusFinal ? '<span style="background:#e9ecef;color:#6c757d;padding:1px 8px;border-radius:10px;font-size:.85em;font-weight:400;text-transform:none">Ditutup</span>' : ''}
          </div>
          <div id="kandidat-chat-${p.id}" style="max-height:200px;overflow-y:auto;margin-bottom:8px;display:flex;flex-direction:column;gap:6px">
            <div style="text-align:center;color:#aaa;font-size:.8em;padding:8px">Memuat pesan...</div>
          </div>
          ${chatInputHtml}
        </div>` : '';

      // Load chat + mulai polling notifikasi
      if (p.id) setTimeout(() => {
        loadKandidatChat(p.id);
        startKandidatChatPoll(p.id);
      }, 500);

      return '<div style="background:#fff;border:1px solid var(--border);border-radius:12px;padding:18px;margin-bottom:12px"><div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px"><div><div style="font-weight:700">'+esc(p.nama)+'</div><div style="font-size:.82em;color:var(--muted)">'+esc(p.posisi_dilamar)+' &middot; '+esc(p.jenis_rekrutmen)+'</div><div style="font-size:.78em;color:var(--muted)">Mendaftar '+tgl(p.dibuat_at)+'</div></div><span style="background:'+stMap.bg+';color:'+stMap.col+';padding:4px 12px;border-radius:20px;font-size:.8em;font-weight:600;white-space:nowrap">'+stMap.ic+' '+stMap.label+'</span></div><div style="font-size:.83em;color:#555;line-height:1.5">'+stMap.msg+'</div>'+timeline+chatSection+'</div>';
    }).join('');
  }catch(e){errEl.textContent='Gagal mengambil data: '+esc(e.message);errEl.style.display='block';}
}

async function cekKodeAkses(){
  const kode=document.getElementById('kode-input').value.trim().toUpperCase();
  const errEl=document.getElementById('kode-error');
  errEl.style.display='none';
  if(!kode){errEl.style.display='block';return;}
  try{
    const data=await sbFetch(`sesi_tes?kode_akses=eq.${kode}&aktif=eq.true`);
    if(!data||!data.length){
      errEl.textContent='Kode akses tidak valid atau sudah tidak aktif.';
      errEl.style.display='block';return;
    }
    currentSesi=data[0];
    // Cek kadaluarsa (3 hari sejak dibuat)
    const expDate=new Date(currentSesi.dibuat_at);
    expDate.setDate(expDate.getDate()+EXPIRY_HARI);
    if(new Date()>expDate){
      // Auto-nonaktifkan di Supabase
      sbFetch('sesi_tes?id=eq.'+currentSesi.id,{method:'PATCH',body:JSON.stringify({aktif:false})}).catch(()=>{});
      errEl.textContent='Kode akses ini sudah kadaluarsa (berlaku 3 hari sejak diterbitkan). Hubungi HR untuk mendapatkan kode baru.';
      errEl.style.display='block';return;
    }
    // Cek apakah sesi sudah pernah dimasuki (kolom dipakai_at terisi)
    if(currentSesi.dipakai_at){
      errEl.textContent='Kode akses ini sudah pernah digunakan dan tidak dapat dipakai kembali. Hubungi HR jika ada kesalahan.';
      errEl.style.display='block';return;
    }
    document.getElementById('kandidat-posisi').value=currentSesi.posisi;
    document.getElementById('kandidat-jenis').value=currentSesi.jenis;
    showPage('page-kandidat-form');
  }catch(e){errEl.textContent='Kode akses tidak valid atau sudah tidak aktif.';errEl.style.display='block';}
}

// mulaiTes defined in test module below

async function loginHR(){
  const email=document.getElementById('hr-email').value.trim();
  const pass=document.getElementById('hr-password').value;
  const errEl=document.getElementById('hr-login-error');
  const btnLogin=document.querySelector('[onclick="loginHR()"]');
  errEl.style.display='none';
  if(!email||!pass){errEl.textContent='Email dan password wajib diisi.';errEl.style.display='block';return;}
  if(btnLogin) btnLogin.disabled=true;
  try{
    const res=await fetch('/api/auth/login',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      credentials:'include',
      body:JSON.stringify({email,password:pass}),
    });
    if(!res.ok){
      const data=await res.json().catch(()=>({}));
      errEl.textContent=data.error||'Email atau password salah.';
      errEl.style.display='block';
      return;
    }
    const akun=await res.json();
    masukDashboardHR(akun);
  }catch(e){
    errEl.textContent='Gagal terhubung ke server.';
    errEl.style.display='block';
  }finally{
    if(btnLogin) btnLogin.disabled=false;
  }
}

function masukDashboardHR(akun){
  hrLoggedIn=akun;
  teardownTabDetection(); // pastikan tab detection tidak aktif di portal HR
  document.getElementById('hr-nama-display').textContent=akun.nama;
  document.getElementById('hr-avatar').textContent=akun.nama.charAt(0).toUpperCase();
  document.querySelectorAll('[id^="page-"]').forEach(p=>p.classList.add('hidden'));
  document.getElementById('page-hr-dashboard').classList.remove('hidden');
  loadHasil(); loadStatistik();
  populatePosisiDropdown();
  startChatBadgePoll(); // Start unread badge polling
}

async function cekSesiHR(){
  try{
    const res=await fetch('/api/auth/session',{credentials:'include'});
    if(res.ok){
      const akun=await res.json();
      if(akun.isLoggedIn){masukDashboardHR(akun);return;}
    }
  }catch(e){}
  showPage('page-landing');
}

async function logoutHR(){
  hrLoggedIn=null;
  try{localStorage.removeItem('crustea_hr_session');}catch(e){}
  try{await fetch('/api/auth/logout',{method:'POST',credentials:'include'});}catch(e){}
  document.getElementById('page-hr-dashboard').classList.add('hidden');
  showPage('page-landing');
}

async function hapusHasil(id, nama) {
  if (!confirm(`Hapus data hasil tes "${nama}"?\n\nData tidak bisa dipulihkan.`)) return;
  try {
    await sbFetch(`hasil_tes?id=eq.${id}`, { method:'DELETE', headers:{'Prefer':'return=minimal'} });
    showToast('Data berhasil dihapus');
    loadHasil();
  } catch(e) {
    alert('Gagal menghapus: ' + e.message);
  }
}

async function loadHasil(){
  const filterJenis=document.getElementById('filter-jenis')?.value||'';
  const search=(document.getElementById('filter-search')?.value||'').toLowerCase();
  let url='hasil_tes?order=selesai_at.desc';
  if(filterJenis) url+=`&jenis=eq.${filterJenis}`;
  document.getElementById('tabel-kandidat').innerHTML=`<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:28px;font-size:.85em">⏳ Memuat data...</td></tr>`;
  try{
    const data=await sbFetch(url);
    allHasil=data||[];
    const filtered=allHasil.filter(h=>!search||h.nama.toLowerCase().includes(search)||h.posisi.toLowerCase().includes(search));
    renderTabelKandidat(filtered);
    renderTabelTerbaru(allHasil.slice(0,5));
  }catch(e){
    document.getElementById('tabel-kandidat').innerHTML=`<tr><td colspan="7" style="text-align:center;color:var(--danger);padding:20px">Gagal memuat data.</td></tr>`;
  }
}

function renderTabelKandidat(data){
  if(!data.length){
    document.getElementById('tabel-kandidat').innerHTML=`<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:24px">Belum ada kandidat.</td></tr>`;return;
  }
  document.getElementById('tabel-kandidat').innerHTML=data.map(h=>{
    const gf=(h.skor_safran?.gf??h.safran_gf??0);
    const cls=gf>=40?'score-high':gf>=25?'score-mid':'score-low';
    const tgl=new Date(h.selesai_at).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
    const _bfE=h.skor_bigfive?.E??h.ocean_e??null;
    const topBF=_bfE!=null?`E:${_bfE} A:${h.skor_bigfive?.A??h.ocean_a??0} C:${h.skor_bigfive?.C??h.ocean_c??0}`:'-';
    return `<tr>
      <td><div style="font-weight:600">${h.nama}</div><div style="font-size:.78em;color:var(--muted)">${h.email}</div></td>
      <td>${h.posisi}</td>
      <td><span class="badge badge-${h.jenis}">${h.jenis}</span></td>
      <td><span class="score-pill ${cls}">${gf}/54</span></td>
      <td style="font-size:.8em;color:var(--muted)">${topBF}</td>
      <td style="font-size:.82em">${tgl}</td>
      <td><button class="btn btn-sm btn-ghost" onclick="lihatDetail('${h.id}')">Detail</button></td>
      <td><button class="btn btn-sm" style="background:var(--danger-light);color:var(--danger);border:1px solid #fca5a5" onclick="hapusHasil('${h.id}','${esc(h.nama)}')" title="Hapus data">🗑</button></td>
    </tr>`;
  }).join('');
}

function renderTabelTerbaru(data){
  if(!data.length){
    document.getElementById('tabel-terbaru').innerHTML=`<tr><td colspan="5" style="text-align:center;color:var(--muted);padding:20px">Belum ada kandidat.</td></tr>`;return;
  }
  document.getElementById('tabel-terbaru').innerHTML=data.map(h=>{
    const gf=(h.skor_safran?.gf??h.safran_gf??0);
    const cls=gf>=40?'score-high':gf>=25?'score-mid':'score-low';
    const tgl=new Date(h.selesai_at).toLocaleDateString('id-ID',{day:'numeric',month:'short'});
    return `<tr>
      <td><div style="font-weight:600">${h.nama}</div></td>
      <td>${h.posisi}</td>
      <td><span class="badge badge-${h.jenis}">${h.jenis}</span></td>
      <td><span class="score-pill ${cls}">${gf}/54</span></td>
      <td style="font-size:.82em">${tgl}</td>
    </tr>`;
  }).join('');
}

const EXPIRY_HARI = 3; // token kadaluarsa setelah N hari

function hitungExpiry(dibuat_at){
  const exp = new Date(dibuat_at);
  exp.setDate(exp.getDate() + EXPIRY_HARI);
  return exp;
}

function statusSesi(s){
  // Prioritas: dipakai > kadaluarsa > nonaktif manual > aktif
  if(s.dipakai_at) return {label:'Terpakai',cls:'nonaktif',color:'#6c757d'};
  const exp = hitungExpiry(s.dibuat_at);
  const expired = new Date() > exp;
  if(expired && s.aktif) return {label:'Kadaluarsa',cls:'nonaktif',color:'#e67e22'};
  if(!s.aktif) return {label:'Nonaktif',cls:'nonaktif',color:'#6c757d'};
  // Aktif: hitung sisa hari
  const sisaMs = exp - new Date();
  const sisaJam = Math.ceil(sisaMs / 3600000);
  const sisaHari = Math.floor(sisaMs / 86400000);
  const sisaLabel = sisaHari > 0 ? sisaHari+'h lagi' : sisaJam+'j lagi';
  return {label:'Aktif · '+sisaLabel, cls:'aktif', color:'var(--green)'};
}

async function loadSesi(){
  try{
    const data=await sbFetch('sesi_tes?order=dibuat_at.desc');
    if(!data||!data.length){
      document.getElementById('tabel-sesi').innerHTML='<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:24px">Belum ada sesi. Buat sesi baru untuk mulai.</td></tr>';return;
    }

    // Auto-nonaktifkan token yang sudah kadaluarsa di Supabase
    const expired = data.filter(s => s.aktif && !s.dipakai_at && new Date() > hitungExpiry(s.dibuat_at));
    expired.forEach(s => {
      sbFetch('sesi_tes?id=eq.'+s.id, {method:'PATCH', body:JSON.stringify({aktif:false})}).catch(()=>{});
    });

    document.getElementById('tabel-sesi').innerHTML=data.map(function(s){
      var tgl=new Date(s.dibuat_at).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
      var exp=hitungExpiry(s.dibuat_at);
      var expTgl=exp.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
      var isExpired = new Date() > exp;
      var expLabel = s.dipakai_at
        ? '<span style="font-size:.78em;color:#6c757d">Terpakai '+new Date(s.dipakai_at).toLocaleDateString('id-ID',{day:'numeric',month:'short'})+'</span>'
        : '<span style="font-size:.78em;color:'+(isExpired?'#e67e22':'var(--muted)')+'">'+expTgl+(isExpired?' ⚠️':'')+'</span>';
      var st = statusSesi(s);
      // Tombol aksi
      var btns='<button class="btn btn-sm btn-ghost" onclick="copyText(\''+s.kode_akses+'\')">Salin</button> ';
      if(!s.dipakai_at && !isExpired){
        if(s.aktif){
          btns+='<button class="btn btn-sm btn-danger" onclick="toggleSesi(\''+s.id+'\',false)">Nonaktifkan</button>';
        }else{
          btns+='<button class="btn btn-sm" onclick="toggleSesi(\''+s.id+'\',true)">Aktifkan</button> ';
        }
      }
      btns+=' <button class="btn btn-sm btn-danger" onclick="hapusSesi(\''+s.id+'\',\''+s.kode_akses+'\')">&#x1F5D1;</button>';
      return '<tr>'
        +'<td><code style="font-size:.9em;font-weight:700;color:'+(st.cls==='aktif'?'var(--green)':'#aaa')+';letter-spacing:1px">'+s.kode_akses+'</code></td>'
        +'<td>'+esc(s.posisi)+'</td>'
        +'<td><span class="badge badge-'+s.jenis+'">'+s.jenis+'</span></td>'
        +'<td style="font-size:.82em;color:var(--muted)">'+(s.catatan?esc(s.catatan):'-')+'</td>'
        +'<td style="font-size:.82em">'+tgl+'</td>'
        +'<td>'+expLabel+'</td>'
        +'<td><span style="background:'+(st.cls==='aktif'?'#d4edda':'#e9ecef')+';color:'+st.color+';padding:3px 10px;border-radius:20px;font-size:.75em;font-weight:600;white-space:nowrap">'+st.label+'</span></td>'
        +'<td style="white-space:nowrap;display:flex;gap:4px">'+btns+'</td>'
        +'</tr>';
    }).join('');
  }catch(e){
    document.getElementById('tabel-sesi').innerHTML='<tr><td colspan="8" style="text-align:center;color:var(--danger)">Gagal memuat sesi.</td></tr>';
  }
}

async function loadStatistik(){
  try{
    const [hasil,sesi,pelamar]=await Promise.all([
      sbFetch('hasil_tes?select=jenis'),
      sbFetch('sesi_tes?select=aktif&aktif=eq.true'),
      sbFetch('pelamar?select=status&status=eq.menunggu')
    ]);
    document.getElementById('stat-pelamar').textContent=pelamar?.length||0;
    document.getElementById('stat-total').textContent=hasil?.length||0;
    document.getElementById('stat-magang').textContent=hasil?.filter(h=>h.jenis==='magang').length||0;
    document.getElementById('stat-karyawan').textContent=hasil?.filter(h=>h.jenis==='karyawan'||h.jenis==='fulltime'||h.jenis==='parttime').length||0;
    document.getElementById('stat-sesi').textContent=sesi?.length||0;
  }catch(e){}
}

