// ===== PIPELINE REKRUTMEN =====
let allPipeline = [];
let currentPipelineId = null;

function stageBadge(result) {
  if(!result || result==='pending') return '<span style="background:#e9ecef;color:#6c757d;padding:2px 8px;border-radius:10px;font-size:.75em">–</span>';
  if(result==='pass'||result==='accept') return '<span style="background:#d4edda;color:#155724;padding:2px 8px;border-radius:10px;font-size:.75em">✅ Pass</span>';
  if(result==='fail'||result==='reject') return '<span style="background:#f8d7da;color:#721c24;padding:2px 8px;border-radius:10px;font-size:.75em">❌ Fail</span>';
  return result;
}

function statusBadgePipeline(s) {
  const map={
    active:'<span style="background:#cce5ff;color:#004085;padding:3px 10px;border-radius:20px;font-size:.75em;font-weight:600">🔄 Active</span>',
    hired:'<span style="background:#d4edda;color:#155724;padding:3px 10px;border-radius:20px;font-size:.75em;font-weight:600">🎉 Hired</span>',
    rejected:'<span style="background:#f8d7da;color:#721c24;padding:3px 10px;border-radius:20px;font-size:.75em;font-weight:600">❌ Rejected</span>',
    withdrawn:'<span style="background:#fff3cd;color:#856404;padding:3px 10px;border-radius:20px;font-size:.75em;font-weight:600">🚶 Withdrawn</span>'
  };
  return map[s]||s;
}

async function loadPipeline() {
  const jenis = document.getElementById('filter-pipeline-jenis')?.value||'';
  const status = document.getElementById('filter-pipeline-status')?.value||'';
  const cari = document.getElementById('filter-pipeline-cari')?.value.toLowerCase()||'';

  try {
    let url = 'pelamar?order=dibuat_at.desc&status=neq.menunggu';
    if(jenis) url += `&jenis_rekrutmen=eq.${jenis}`;
    if(status) url += `&status_akhir=eq.${status}`;
    const data = await sbFetch(url);
    allPipeline = (data||[]).filter(p=>
      !cari||(p.nama||'').toLowerCase().includes(cari)||(p.posisi_dilamar||'').toLowerCase().includes(cari)
    );

    // Summary cards
    const total=allPipeline.length;
    const active=allPipeline.filter(p=>p.status_akhir==='active').length;
    const hired=allPipeline.filter(p=>p.status_akhir==='hired').length;
    const rejected=allPipeline.filter(p=>p.status_akhir==='rejected').length;
    const withdrawn=allPipeline.filter(p=>p.status_akhir==='withdrawn').length;
    document.getElementById('pipeline-summary').innerHTML=`
      <div class="stat-card" style="padding:12px"><div class="stat-num" style="font-size:1.4em">${total}</div><div class="stat-label">Total</div></div>
      <div class="stat-card" style="padding:12px;border-left:3px solid #004085"><div class="stat-num" style="font-size:1.4em;color:#004085">${active}</div><div class="stat-label">Active</div></div>
      <div class="stat-card" style="padding:12px;border-left:3px solid var(--green)"><div class="stat-num" style="font-size:1.4em;color:var(--green)">${hired}</div><div class="stat-label">Hired</div></div>
      <div class="stat-card" style="padding:12px;border-left:3px solid var(--danger)"><div class="stat-num" style="font-size:1.4em;color:var(--danger)">${rejected}</div><div class="stat-label">Rejected</div></div>
      <div class="stat-card" style="padding:12px;border-left:3px solid #856404"><div class="stat-num" style="font-size:1.4em;color:#856404">${withdrawn}</div><div class="stat-label">Withdrawn</div></div>
    `;

    const tbody = document.getElementById('tabel-pipeline');
    if(!allPipeline.length){
      tbody.innerHTML='<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--muted)">Belum ada data pipeline.</td></tr>';
      return;
    }

    tbody.innerHTML = allPipeline.map(p => {
      const tgl = p.dibuat_at ? new Date(p.dibuat_at).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}) : '–';
      return `<tr style="border-bottom:1px solid var(--border)">
        <td style="padding:8px;white-space:nowrap"><strong>${p.nama}</strong><br><span style="font-size:.75em;color:var(--muted)">${tgl}</span></td>
        <td style="padding:8px;white-space:nowrap">${p.posisi_dilamar}</td>
        <td style="padding:8px"><span class="badge ${jenisBadgeClass(p.jenis_rekrutmen)}" style="font-size:.75em">${jenisLabel(p.jenis_rekrutmen)}</span></td>
        <td style="padding:8px;font-size:.8em">${p.source||'–'}</td>
        <td style="padding:8px;text-align:center">${stageBadge(p.result_seleksi_berkas)}</td>
        <td style="padding:8px;text-align:center">${stageBadge(p.result_psikotest)}</td>
        <td style="padding:8px;text-align:center">${stageBadge(p.result_interview)}</td>
        <td style="padding:8px;text-align:center">${stageBadge(p.result_offering)}</td>
        <td style="padding:8px;text-align:center">${statusBadgePipeline(p.status_akhir||'active')}</td>
        <td style="padding:8px;text-align:center">
          <button class="btn btn-sm btn-ghost" onclick="editPipeline('${p.id}')" style="font-size:.75em;padding:4px 10px">✏️ Edit</button>
        </td>
      </tr>`;
    }).join('');
  } catch(e) {
    document.getElementById('tabel-pipeline').innerHTML=`<tr><td colspan="10" style="text-align:center;color:var(--danger);padding:20px">Gagal memuat pipeline: ${e.message}</td></tr>`;
  }
}

function editPipeline(id) {
  const p = allPipeline.find(x=>x.id===id);
  if(!p) return;
  currentPipelineId = id;

  document.getElementById('pipeline-modal-nama').textContent = p.nama;
  document.getElementById('pipeline-modal-info').textContent = `${p.posisi_dilamar} · ${p.jenis_rekrutmen} · ${p.email}`;

  // Fill form
  const set = (id, val) => { const el=document.getElementById(id); if(el&&val) el.value=val; };
  set('pm-tgl-berkas', p.tgl_seleksi_berkas);
  set('pm-result-berkas', p.result_seleksi_berkas||'pending');
  set('pm-tgl-psiko', p.tgl_psikotest);
  set('pm-result-psiko', p.result_psikotest||'pending');
  set('pm-tgl-interview', p.tgl_interview);
  set('pm-interviewer', p.interviewer);
  set('pm-result-interview', p.result_interview||'pending');
  set('pm-tgl-offering', p.tgl_offering);
  set('pm-result-offering', p.result_offering||'pending');
  set('pm-status-akhir', p.status_akhir||'active');

  // Reset all rating buttons
  document.querySelectorAll('[data-key]').forEach(b=>{
    b.style.background='var(--card)';b.style.color='var(--text)';b.style.borderColor='var(--border)';
  });
  document.querySelectorAll('input[id^="r-"]').forEach(i=>i.value='0');
  // Reset catatan fields
  ['pm-catatan-berkas','pm-catatan-psiko','pm-catatan-interview','pm-catatan-offering','pm-catatan'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
  const rekEl=document.getElementById('pm-rekomendasi'); if(rekEl) rekEl.value='';

  // Load JSON notes
  loadRatingsToUI(p.catatan_hr);

  // Reset to first tab
  switchPmTab('berkas');
  document.getElementById('modal-pipeline').classList.remove('hidden');
}

async function savePipeline() {
  if(!currentPipelineId) return;
  try {
    const payload = {
      tgl_seleksi_berkas: document.getElementById('pm-tgl-berkas').value||null,
      result_seleksi_berkas: document.getElementById('pm-result-berkas').value,
      tgl_psikotest: document.getElementById('pm-tgl-psiko').value||null,
      result_psikotest: document.getElementById('pm-result-psiko').value,
      tgl_interview: document.getElementById('pm-tgl-interview').value||null,
      interviewer: document.getElementById('pm-interviewer').value||null,
      result_interview: document.getElementById('pm-result-interview').value,
      tgl_offering: document.getElementById('pm-tgl-offering').value||null,
      result_offering: document.getElementById('pm-result-offering').value,
      status_akhir: document.getElementById('pm-status-akhir').value,
      catatan_hr: getRatingsFromUI()||null
    };
    const prevData = (await sbFetch(`pelamar?id=eq.${currentPipelineId}&select=status_akhir`))?.[0];
    await sbFetch(`pelamar?id=eq.${currentPipelineId}`, {method:'PATCH', body:JSON.stringify(payload)});

    // Kirim pesan otomatis jika status akhir baru = hired
    if (payload.status_akhir === 'hired' && prevData?.status_akhir !== 'hired') {
      await kirimPesanOtomatis(currentPipelineId, 'hired');
    }

    closeModal('modal-pipeline');
    loadPipeline();
    // Toast
    const t=document.createElement('div');
    t.style.cssText='position:fixed;bottom:24px;right:24px;background:var(--green);color:#fff;padding:12px 20px;border-radius:10px;z-index:9999;font-size:.88em';
    t.textContent='✅ Pipeline diperbarui!';
    document.body.appendChild(t);
    setTimeout(()=>t.remove(),3000);
  } catch(e) {
    alert('Gagal menyimpan: '+e.message);
  }
}



// ===== KPI & ANALITIK =====
const TAHAP_REKAP=[['Seleksi Berkas','tgl_seleksi_berkas','result_seleksi_berkas','pass','fail'],['Psikotes','tgl_psikotest','result_psikotest','pass','fail'],['Interview','tgl_interview','result_interview','pass','fail'],['Offering','tgl_offering','result_offering','accept','reject']];
let kpiChart=null;

function setKpiPeriod(btn, val){
  document.querySelectorAll('.kpi-period-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  const now=new Date();
  const fmt=d=>d.toISOString().slice(0,10);
  const dari=document.getElementById('rk-dari');
  const sampai=document.getElementById('rk-sampai');
  if(val==='semua'){dari.value='';sampai.value='';}
  else if(val==='bulan-ini'){dari.value=fmt(new Date(now.getFullYear(),now.getMonth(),1));sampai.value=fmt(now);}
  else if(val==='bulan-lalu'){const d=new Date(now.getFullYear(),now.getMonth()-1,1);dari.value=fmt(d);sampai.value=fmt(new Date(now.getFullYear(),now.getMonth(),0));}
  else if(val==='tahun-ini'){dari.value=fmt(new Date(now.getFullYear(),0,1));sampai.value=fmt(now);}
  else{const d=new Date(now);d.setDate(d.getDate()-val);dari.value=fmt(d);sampai.value=fmt(now);}
  loadRekap();
}

function onKpiDateChange(){
  document.querySelectorAll('.kpi-period-btn').forEach(b=>b.classList.remove('active'));
  loadRekap();
}

function tahapBerjalan(p){for(const [lbl,,res,,no] of TAHAP_REKAP){const r=p[res];if(r===no) return null;if(!r||r==='pending') return {lbl};}return null;}
function tglTerakhir(p){const ds=[p.dibuat_at,...TAHAP_REKAP.map(t=>p[t[1]])].filter(Boolean).map(d=>new Date(d).getTime());return Math.max(...ds);}

function renderCorong(rows, proses, hired){
  const total=rows.length;
  const disetujui=proses.length;
  const mulaiTesCount=proses.filter(p=>p.tgl_seleksi_berkas).length;
  const selesaiTes=proses.filter(p=>p.result_seleksi_berkas==='pass'||p.result_seleksi_berkas==='fail').length;
  const lolosInterview=proses.filter(p=>p.result_interview==='pass').length;
  const offering=proses.filter(p=>p.tgl_offering).length;
  const stages=[
    {label:'Mendaftar',val:total,color:'#2563eb'},
    {label:'Disetujui HR',val:disetujui,color:'#2563eb'},
    {label:'Mulai Seleksi',val:mulaiTesCount,color:'#1d7ae8'},
    {label:'Lolos Interview',val:lolosInterview,color:'#1a7a5e'},
    {label:'Offering',val:offering,color:'#0d6e5a'},
    {label:'Diterima',val:hired,color:'#0a5a48'},
  ];
  const el=document.getElementById('rk-corong');
  if(!el) return;
  el.innerHTML=stages.map((st,i)=>{
    const pct=total>0?Math.round(st.val/total*100):0;
    const drop=i>0?stages[i-1].val-st.val:0;
    const dropPct=i>0&&stages[i-1].val>0?Math.round(drop/stages[i-1].val*100):0;
    return `<div class="kpi-corong-row">
      <div class="kpi-corong-label"><span>${st.label}</span><span style="font-weight:700">${st.val} &middot; <span style="color:var(--muted);font-weight:400">${pct}%</span></span></div>
      <div class="kpi-corong-bar-bg"><div class="kpi-corong-bar-fill" style="width:${pct}%;background:${st.color}"><span style="font-size:.72em;color:#fff;font-weight:700">${pct>15?pct+'%':''}</span></div></div>
      ${i>0&&drop>0?`<div class="kpi-corong-drop">-${drop} kandidat (${dropPct}%) dari tahap sebelumnya</div>`:''}
    </div>`;
  }).join('');
}

function renderTrenChart(rows, hasilRows){
  const dari=document.getElementById('rk-dari')?.value||'';
  const sampai=document.getElementById('rk-sampai')?.value||'';
  // Tentukan granularitas: jika rentang > 60 hari, pakai minggu
  const d1=dari?new Date(dari):new Date(Math.min(...rows.map(r=>new Date(r.dibuat_at)).filter(d=>!isNaN(d))));
  const d2=sampai?new Date(sampai):new Date();
  const selisihHari=(d2-d1)/864e5;
  const byWeek=selisihHari>60;

  const fmt=d=>{
    const dd=new Date(d);
    if(byWeek){const w=new Date(dd);w.setDate(dd.getDate()-dd.getDay());return w.toISOString().slice(0,10);}
    return dd.toISOString().slice(0,10);
  };
  const labelFmt=k=>{
    const d=new Date(k);
    return byWeek?d.toLocaleDateString('id-ID',{day:'numeric',month:'short'}):d.toLocaleDateString('id-ID',{day:'numeric',month:'short'});
  };

  // Kumpulkan semua key (tanggal/minggu) dalam rentang
  const keys=new Set();
  let cur=new Date(d1);
  while(cur<=d2){keys.add(fmt(cur));cur.setDate(cur.getDate()+(byWeek?7:1));}
  const sortedKeys=[...keys].sort();

  // Hitung per key
  const pelamar={},selesai={},diterima={};
  sortedKeys.forEach(k=>{pelamar[k]=0;selesai[k]=0;diterima[k]=0;});
  rows.forEach(p=>{const k=fmt(p.dibuat_at);if(pelamar[k]!==undefined) pelamar[k]++;});
  (hasilRows||[]).forEach(h=>{if(h.selesai_at){const k=fmt(h.selesai_at);if(selesai[k]!==undefined) selesai[k]++;}});
  rows.filter(p=>p.status_akhir==='hired'&&p.tgl_offering).forEach(p=>{const k=fmt(p.tgl_offering);if(diterima[k]!==undefined) diterima[k]++;});

  const labels=sortedKeys.map(labelFmt);
  const canvas=document.getElementById('rk-chart-tren');
  if(!canvas) return;
  if(kpiChart){kpiChart.destroy();kpiChart=null;}
  if(typeof Chart==='undefined') return;
  kpiChart=new Chart(canvas,{
    type:'line',
    data:{
      labels,
      datasets:[
        {label:'Pelamar',data:sortedKeys.map(k=>pelamar[k]),borderColor:'#2563eb',backgroundColor:'rgba(37,99,235,.08)',fill:true,tension:.4,pointRadius:3},
        {label:'Tuntas tes',data:sortedKeys.map(k=>selesai[k]),borderColor:'#1a7a5e',backgroundColor:'rgba(26,122,94,.08)',fill:true,tension:.4,pointRadius:3},
        {label:'Diterima',data:sortedKeys.map(k=>diterima[k]),borderColor:'#f59e0b',backgroundColor:'rgba(245,158,11,.08)',fill:false,tension:.4,pointRadius:3,borderDash:[4,3]},
      ]
    },
    options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top',labels:{boxWidth:12,font:{size:11}}}},scales:{x:{grid:{display:false},ticks:{font:{size:10},maxRotation:45}},y:{beginAtZero:true,grid:{color:'rgba(0,0,0,.05)'},ticks:{font:{size:10},stepSize:1}}}}
  });
}

async function loadRekap(){
  const dari=document.getElementById('rk-dari')?.value||'';
  const sampai=document.getElementById('rk-sampai')?.value||'';
  const jenis=document.getElementById('rk-jenis')?.value||'';
  const kpiEl=document.getElementById('rk-kpi');
  if(kpiEl) kpiEl.innerHTML='<div style="color:var(--muted);font-size:.85em;grid-column:1/-1">Memuat...</div>';
  try{
    let url='pelamar?order=dibuat_at.desc';
    if(dari) url+='&dibuat_at=gte.'+dari;
    if(sampai) url+='&dibuat_at=lte.'+sampai+'T23:59:59';
    if(jenis) url+='&jenis_rekrutmen=eq.'+jenis;
    const rows = await sbFetch(url);
    let hasilRows = [];
    try{ hasilRows = await sbFetch('hasil_tes?select=selesai_at,sesi_id&order=selesai_at.desc') || []; }
    catch(e){ console.warn('hasil_tes tidak bisa dimuat:', e.message); }
    const all=rows||[], hasil=hasilRows;
    const now=Date.now(), hari=ms=>Math.floor(ms/864e5);
    const total=all.length;
    const menunggu=all.filter(p=>p.status==='menunggu').length;
    const proses=all.filter(p=>p.status==='disetujui');
    const aktif=proses.filter(p=>(p.status_akhir||'active')==='active');
    const hired=proses.filter(p=>p.status_akhir==='hired').length;
    const ditolak=all.filter(p=>p.status==='ditolak').length;
    const approvalRate=total>0?Math.round((proses.length/total)*100):0;
    const completionRate=proses.length>0?Math.round((hasil.length/proses.length)*100):0;
    const th2=proses.filter(p=>p.status_akhir==='hired'&&p.tgl_offering&&p.dibuat_at).map(p=>(new Date(p.tgl_offering)-new Date(p.dibuat_at))/864e5);
    const tth=th2.length?Math.round(th2.reduce((a,b)=>a+b,0)/th2.length)+' hr':'—';
    const stuck=aktif.map(p=>{const cur=tahapBerjalan(p);if(!cur) return null;const lama=hari(now-tglTerakhir(p));return lama>7?{p,cur,lama}:null;}).filter(Boolean).sort((a,b)=>b.lama-a.lama);

    // KPI Cards
    const kpi=(ic,num,lbl,sub,col,action)=>`<div class="stat-card${action?' kpi-clickable':''}" ${action?`onclick="${action}" title="Klik untuk detail"`:''}style="${action?'cursor:pointer;':''}"><div class="stat-icon">${ic}</div><div class="stat-num" style="color:${col||'inherit'}">${num}</div><div class="stat-label">${lbl}</div>${sub?`<div style="font-size:.72em;color:var(--muted);margin-top:2px">${sub}</div>`:''}</div>`;
    if(kpiEl) kpiEl.innerHTML=
      kpi('📥',total,'Total Pelamar',`${menunggu} menunggu review`,'','switchMenu(&quot;pelamar&quot;)')+
      kpi('✅',proses.length,'Disetujui',`Approval rate: ${approvalRate}%`,'var(--green)','switchMenu(&quot;pipeline&quot;)')+
      kpi('🔄',aktif.length,'Aktif di Proses',`${ditolak} ditolak`,'','switchMenu(&quot;pipeline&quot;)')+
      kpi('🎉',hired,'Hired',`dari ${proses.length} yang diproses`,'var(--green)','switchMenu(&quot;kandidat&quot;)')+
      kpi('⏱️',tth,'Rata-rata Time-to-Hire','','','document.getElementById(&quot;rk-tth-container&quot;)?.scrollIntoView({behavior:&quot;smooth&quot;,block:&quot;center&quot;})')+
      kpi('⚠️',stuck.length,'Tertahan > 7 Hari','Perlu tindakan HR',stuck.length>0?'var(--danger)':'inherit','document.getElementById(&quot;rk-stuck&quot;)?.closest(&quot;.card&quot;)?.scrollIntoView({behavior:&quot;smooth&quot;,block:&quot;center&quot;})');

    // Corong
    renderCorong(all, proses, hired);

    // Tren
    renderTrenChart(all, hasil);

    // Bar charts
    const grup=(key,data)=>Object.entries((data||all).reduce((m,p)=>{const k=p[key]||'(kosong)';m[k]=(m[k]||0)+1;return m;},{})).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([label,val])=>({label:esc(label),val}));
    const bar=(id,key,color,data)=>{const d=grup(key,data);if(!d.length){const el=document.getElementById(id);if(el)el.innerHTML='<p style="color:var(--muted);font-size:.85em">Belum ada data.</p>';return;}renderBar(id,d,Math.max(...d.map(x=>x.val),1),()=>color);};
    bar('rk-source','source','#2471a3');
    bar('rk-posisi','posisi_dilamar','#1a7a5e');

    // Tertahan
    const scEl=document.getElementById('rk-stuck-count');
    const stEl=document.getElementById('rk-stuck');
    if(scEl) scEl.textContent=stuck.length?'('+stuck.length+')':'';
    if(stEl) stEl.innerHTML=stuck.length?stuck.map(function({p,cur,lama}){return '<tr><td><strong>'+esc(p.nama)+'</strong></td><td>'+esc(p.posisi_dilamar)+'</td><td>'+esc(cur.lbl)+'</td><td>'+new Date(tglTerakhir(p)).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})+'</td><td style="color:var(--danger);font-weight:700">'+lama+' hari</td><td><button class="btn btn-sm btn-ghost" onclick="editPipeline(this.dataset.id)" data-id="'+esc(p.id)+'" style="font-size:.75em">✏️ Edit</button></td></tr>';}).join(''):'<tr><td colspan="6" style="text-align:center;color:var(--muted);padding:16px">Tidak ada kandidat tertahan 🎉</td></tr>';

    // Beban interviewer
    const beban={};aktif.filter(p=>p.interviewer&&(!p.result_interview||p.result_interview==='pending')).forEach(p=>{beban[p.interviewer]=(beban[p.interviewer]||0)+1;});
    const bd=Object.entries(beban).sort((a,b)=>b[1]-a[1]).map(([label,val])=>({label:esc(label),val}));
    const ivEl=document.getElementById('rk-interviewer');
    if(ivEl){if(bd.length) renderBar('rk-interviewer',bd,Math.max(...bd.map(x=>x.val),1),()=>'#8e44ad');else ivEl.innerHTML='<p style="color:var(--muted);font-size:.85em">Tidak ada kandidat aktif di tahap interview.</p>';}

    // Time to Hire
    const tthEl=document.getElementById('rk-tth-container');
    if(tthEl){
      const hiredAll=proses.filter(p=>p.status_akhir==='hired'&&p.dibuat_at);
      const avg=(arr)=>arr.length?Math.round(arr.reduce((a,b)=>a+b,0)/arr.length):null;
      const daysBetween=(a,b)=>a&&b?(new Date(b)-new Date(a))/864e5:null;
      const stages=[
        {id:'pendaftaran-seleksi',lbl:'Pendaftaran → Seleksi Berkas',icon:'📋',
          vals:hiredAll.map(p=>daysBetween(p.dibuat_at,p.tgl_psikotest||p.tgl_interview||p.tgl_offering)).filter(v=>v!==null&&v>=0)},
        {id:'seleksi-psikotest',lbl:'Seleksi Berkas → Psikotest',icon:'🧠',
          vals:hiredAll.filter(p=>p.tgl_psikotest).map(p=>daysBetween(p.dibuat_at,p.tgl_psikotest)).filter(v=>v!==null&&v>=0)},
        {id:'psikotest-interview',lbl:'Psikotest → Interview',icon:'🎙️',
          vals:hiredAll.filter(p=>p.tgl_psikotest&&p.tgl_interview).map(p=>daysBetween(p.tgl_psikotest,p.tgl_interview)).filter(v=>v!==null&&v>=0)},
        {id:'interview-offering',lbl:'Interview → Offering',icon:'📄',
          vals:hiredAll.filter(p=>p.tgl_interview&&p.tgl_offering).map(p=>daysBetween(p.tgl_interview,p.tgl_offering)).filter(v=>v!==null&&v>=0)},
        {id:'total',lbl:'Total (Pendaftaran → Hired)',icon:'🏁',
          vals:th2,highlight:true},
      ];
      const maxAvg=Math.max(...stages.map(s=>avg(s.vals)||0),1);
      if(!hiredAll.length){
        tthEl.innerHTML='<p style="color:var(--muted);font-size:.85em;text-align:center;padding:16px 0">Belum ada kandidat dengan status <strong>Hired</strong>. Data akan muncul setelah ada kandidat yang berhasil di-hire.</p>';
      } else {
        tthEl.innerHTML=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-bottom:20px">${
          stages.map(s=>{
            const a=avg(s.vals);
            const pct=a?Math.round((a/maxAvg)*100):0;
            return `<div style="padding:14px 16px;border-radius:10px;background:${s.highlight?'rgba(16,122,94,.08)':'var(--bg-secondary, #f8fafa)'};border:1px solid ${s.highlight?'rgba(16,122,94,.2)':'var(--border)'}">
              <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
                <span style="font-size:1.1em">${s.icon}</span>
                <span style="font-size:.8em;font-weight:600;color:var(--muted)">${s.lbl}</span>
              </div>
              <div style="font-size:1.6em;font-weight:700;color:${s.highlight?'var(--green)':'var(--text)'};margin-bottom:6px">${a!==null?a+' hari':'—'}</div>
              <div style="background:var(--border);border-radius:4px;height:6px;overflow:hidden">
                <div style="width:${pct}%;height:100%;background:${s.highlight?'var(--green)':'#3498db'};border-radius:4px;transition:.4s"></div>
              </div>
              <div style="font-size:.75em;color:var(--muted);margin-top:6px">Dari ${s.vals.length} kandidat hired</div>
            </div>`;
          }).join('')
        }</div>
        <div style="overflow-x:auto">
          <table style="font-size:.82em;width:100%">
            <thead><tr><th>Nama</th><th>Posisi</th><th>Tgl Daftar</th><th>Tgl Psikotest</th><th>Tgl Interview</th><th>Tgl Offering</th><th style="color:var(--green)">Total Hari</th></tr></thead>
            <tbody>${hiredAll.slice(0,15).map(p=>{
              const total=p.tgl_offering?Math.round(daysBetween(p.dibuat_at,p.tgl_offering)):null;
              return `<tr>
                <td><strong>${esc(p.nama||'-')}</strong></td>
                <td>${esc(p.posisi_dilamar||'-')}</td>
                <td>${p.dibuat_at?new Date(p.dibuat_at).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'-'}</td>
                <td>${p.tgl_psikotest?new Date(p.tgl_psikotest).toLocaleDateString('id-ID',{day:'numeric',month:'short'}):'-'}</td>
                <td>${p.tgl_interview?new Date(p.tgl_interview).toLocaleDateString('id-ID',{day:'numeric',month:'short'}):'-'}</td>
                <td>${p.tgl_offering?new Date(p.tgl_offering).toLocaleDateString('id-ID',{day:'numeric',month:'short'}):'-'}</td>
                <td style="font-weight:700;color:var(--green)">${total!==null?total+' hr':'-'}</td>
              </tr>`;
            }).join('')}
            </tbody>
          </table>
          ${hiredAll.length>15?`<p style="font-size:.78em;color:var(--muted);text-align:center;margin-top:8px">Menampilkan 15 dari ${hiredAll.length} kandidat hired.</p>`:''}
        </div>`;
      }
    }

  }catch(e){
    if(kpiEl) kpiEl.innerHTML='<div style="color:var(--danger);grid-column:1/-1">Gagal memuat: '+esc(e.message)+'</div>';
    console.error(e);
  }
}


// ===== TEMPLATE PESAN =====
const TPL_KEY='crustea_templates';
const TPL_DEFAULTS=[
  {id:'tpl_1',nama:'Undangan Interview',kategori:'undangan',isi:'Yth. {nama},\n\nTerima kasih atas minat Anda melamar di Crustea. Kami dengan senang hati mengundang Anda untuk mengikuti sesi interview bersama tim kami.\n\nJadwal interview akan dikonfirmasi lebih lanjut melalui pesan ini. Mohon balas pesan ini untuk konfirmasi kehadiran Anda.\n\nSalam,\nTim HR Crustea'},
  {id:'tpl_2',nama:'Konfirmasi Psikotest',kategori:'undangan',isi:'Yth. {nama},\n\nLamaran Anda telah kami setujui. Silakan gunakan kode akses yang telah dikirimkan untuk mengikuti psikotest online.\n\nPastikan:\n• Koneksi internet stabil\n• Menggunakan laptop/PC\n• Kamera aktif\n• Berada di ruangan yang tenang\n\nSalam,\nTim HR Crustea'},
  {id:'tpl_3',nama:'Penolakan Lamaran',kategori:'penolakan',isi:'Yth. {nama},\n\nTerima kasih atas waktu dan minat Anda melamar di Crustea. Setelah melalui proses seleksi, kami menyampaikan bahwa pada kesempatan ini kami belum dapat melanjutkan lamaran Anda.\n\nKami menghargai minat Anda dan mendoakan yang terbaik untuk perjalanan karier Anda.\n\nSalam,\nTim HR Crustea'},
  {id:'tpl_4',nama:'Info Jadwal Offering',kategori:'info',isi:'Yth. {nama},\n\nSelamat! Anda telah berhasil melewati seluruh tahap seleksi. Kami akan menghubungi Anda dalam waktu dekat untuk mendiskusikan penawaran kerja (offering).\n\nMohon siapkan dokumen pendukung yang dibutuhkan.\n\nSalam,\nTim HR Crustea'},
];

function getTemplates(){
  try{ const s=localStorage.getItem(TPL_KEY); return s?JSON.parse(s):JSON.parse(JSON.stringify(TPL_DEFAULTS)); }
  catch(e){ return JSON.parse(JSON.stringify(TPL_DEFAULTS)); }
}
function saveTemplates(arr){ try{ localStorage.setItem(TPL_KEY,JSON.stringify(arr)); }catch(e){} }

let _tplEditId=null, _tplFilterTag='';

function renderTemplatePanel(){
  const arr=getTemplates();
  const filtered=_tplFilterTag?arr.filter(t=>t.kategori===_tplFilterTag):arr;
  const el=document.getElementById('tpl-list');
  if(!el) return;
  if(!filtered.length){
    el.innerHTML='<p style="color:var(--muted);font-size:.85em;text-align:center;padding:24px 0">Belum ada template. Klik "+ Tambah Template" untuk membuat.</p>';
    return;
  }
  el.innerHTML=filtered.map(t=>`
    <div class="tpl-card">
      <div style="flex:1;min-width:0">
        <span class="tpl-badge ${t.kategori}">${t.kategori.charAt(0).toUpperCase()+t.kategori.slice(1)}</span>
        <div style="font-weight:700;font-size:.92em;margin-bottom:4px">${esc(t.nama)}</div>
        <div style="font-size:.8em;color:var(--muted);line-height:1.5;white-space:pre-wrap;max-height:60px;overflow:hidden">${esc(t.isi)}</div>
      </div>
      <div style="display:flex;flex-direction:column;gap:6px;min-width:80px;align-items:flex-end">
        <button class="btn btn-sm" onclick="copyTemplate('${t.id}')" title="Salin teks">📋 Salin</button>
        <button class="btn btn-sm btn-ghost" onclick="openTemplateModal('${t.id}')">✏️ Edit</button>
        <button class="btn btn-sm btn-ghost" onclick="deleteTemplate('${t.id}')" style="color:var(--danger)">🗑️</button>
      </div>
    </div>`).join('');
}

function filterTemplateTag(btn,tag){
  _tplFilterTag=tag;
  document.querySelectorAll('.tpl-tag-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  renderTemplatePanel();
}

function openTemplateModal(id){
  _tplEditId=id||null;
  const modal=document.getElementById('modal-template');
  document.getElementById('tpl-modal-title').textContent=id?'Edit Template':'Tambah Template';
  if(id){
    const t=getTemplates().find(x=>x.id===id);
    if(t){
      document.getElementById('tpl-nama').value=t.nama;
      document.getElementById('tpl-kategori').value=t.kategori;
      document.getElementById('tpl-isi').value=t.isi;
    }
  } else {
    document.getElementById('tpl-nama').value='';
    document.getElementById('tpl-kategori').value='undangan';
    document.getElementById('tpl-isi').value='';
  }
  modal.style.display='flex';
}

function closeTemplateModal(){
  document.getElementById('modal-template').style.display='none';
  _tplEditId=null;
}

function saveTemplate(){
  const nama=document.getElementById('tpl-nama').value.trim();
  const kategori=document.getElementById('tpl-kategori').value;
  const isi=document.getElementById('tpl-isi').value.trim();
  if(!nama||!isi){ alert('Nama dan isi template wajib diisi.'); return; }
  const arr=getTemplates();
  if(_tplEditId){
    const idx=arr.findIndex(t=>t.id===_tplEditId);
    if(idx>=0) arr[idx]={...arr[idx],nama,kategori,isi};
  } else {
    arr.push({id:'tpl_'+Date.now(),nama,kategori,isi});
  }
  saveTemplates(arr);
  closeTemplateModal();
  renderTemplatePanel();
}

function deleteTemplate(id){
  if(!confirm('Hapus template ini?')) return;
  const arr=getTemplates().filter(t=>t.id!==id);
  saveTemplates(arr);
  renderTemplatePanel();
}

function copyTemplate(id){
  const t=getTemplates().find(x=>x.id===id);
  if(!t) return;
  navigator.clipboard.writeText(t.isi).then(()=>{
    const btn=event.target;
    const orig=btn.textContent;
    btn.textContent='✅ Disalin!';
    setTimeout(()=>btn.textContent=orig,1500);
  }).catch(()=>{ alert('Teks template:\n\n'+t.isi); });
}

function useTemplateInChat(id, pelamarId, namKandidat){
  const t=getTemplates().find(x=>x.id===id);
  if(!t) return;
  const isi=t.isi.replace(/\{nama\}/g, namKandidat||'Kandidat');
  const inp=document.getElementById('chat-input-'+pelamarId)||document.getElementById('chat-input');
  if(inp){ inp.value=isi; inp.focus(); }
}

function renderChatTemplateBar(kandidatNama){
  const bar=document.getElementById('chat-template-bar');
  if(!bar) return;
  const tpls=getTemplates();
  if(!tpls.length){ bar.style.display='none'; return; }
  bar.style.display='flex';
  const katLabel={undangan:'📅',penolakan:'❌',info:'ℹ️',lainnya:'💬'};
  const safeName=(kandidatNama||'Kandidat').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
  bar.innerHTML=tpls.map(tp=>`<button onclick="applyTplToChat('${tp.id}','${safeName}')" title="${esc(tp.nama)}" style="padding:3px 10px;border:1px solid var(--border);border-radius:14px;background:#fff;font-size:.75em;cursor:pointer;white-space:nowrap;transition:.15s;color:var(--text)" onmouseover="this.style.borderColor='var(--green)';this.style.color='var(--green)'" onmouseout="this.style.borderColor='var(--border)';this.style.color='var(--text)'">${katLabel[tp.kategori]||'💬'} ${esc(tp.nama)}</button>`).join('');
}

function applyTplToChat(id, namaKandidat){
  const tpl=getTemplates().find(x=>x.id===id);
  if(!tpl) return;
  const inp=document.getElementById('chat-input');
  if(inp){ inp.value=tpl.isi.replace(/\{nama\}/g, namaKandidat||'Kandidat'); inp.focus(); }
}

function exportPipelineExcel() {
  if(!allPipeline.length){ alert('Tidak ada data untuk diexport.'); return; }
  const headers = ['Nama','Email','No HP','NIK','Posisi','Jenis','Source','Lokasi','Tgl Daftar','Seleksi Berkas','Tgl Psikotest','Result Psikotest','Tgl Interview','Interviewer','Result Interview','Tgl Offering','Result Offering','Status Akhir','Catatan HR'];
  const rows = allPipeline.map(p=>[
    p.nama,p.email,p.no_hp,p.nik,p.posisi_dilamar,p.jenis_rekrutmen,p.source,p.lokasi_penempatan,
    p.dibuat_at?new Date(p.dibuat_at).toLocaleDateString('id-ID'):'',
    p.result_seleksi_berkas,p.tgl_psikotest,p.result_psikotest,
    p.tgl_interview,p.interviewer,p.result_interview,
    p.tgl_offering,p.result_offering,p.status_akhir,p.catatan_hr
  ]);
  const bom='﻿';
  const csv=bom+[headers,...rows].map(r=>r.map(c=>`"${(c||'').toString().replace(/"/g,'""')}"`).join(',')).join('\n');
  const a=document.createElement('a');
  a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);
  a.download='pipeline_rekrutmen_crustea.csv';
  a.click();
}

