// ===== UPLOAD FILE TO SUPABASE STORAGE =====
async function uploadFile(file, path){
  const res = await fetch(`/api/storage?path=${encodeURIComponent(path)}`, {
    method: 'POST',
    headers: { 'Content-Type': file.type },
    credentials: 'include',
    body: file
  });
  if(!res.ok){ const t=await res.text(); throw new Error(t); }
  const { url } = await fetch(`/api/storage?action=public-url&path=${encodeURIComponent(path)}`).then(r=>r.json());
  return url;
}

// ===== SUBMIT LAMARAN =====
async function submitLamaran(){
  const err=document.getElementById('daftar-error');
  const loading=document.getElementById('daftar-loading');
  err.style.display='none';

  // Validasi wajib
  const fields=[
    {id:'daftar-posisi',label:'Posisi'},
    {id:'daftar-nama',label:'Nama'},
    {id:'daftar-email',label:'Email'},
    {id:'daftar-hp',label:'No. HP'},
    {id:'daftar-tempat-lahir',label:'Tempat Lahir'},
    {id:'daftar-tanggal-lahir',label:'Tanggal Lahir'},
    {id:'daftar-jk',label:'Jenis Kelamin'},
    {id:'daftar-alamat',label:'Alamat'},
    {id:'daftar-pendidikan',label:'Pendidikan'},
    {id:'daftar-institusi',label:'Institusi'},
    {id:'daftar-jurusan',label:'Jurusan'},
    {id:'daftar-tahun-lulus',label:'Tahun Lulus'},
    {id:'daftar-motivasi',label:'Motivasi'},
    {id:'daftar-nik',label:'NIK'},
    {id:'daftar-source',label:'Sumber Informasi'},
    {id:'daftar-lokasi',label:'Lokasi Penempatan'}
  ];
  for(const f of fields){
    if(!document.getElementById(f.id).value.trim()){
      err.textContent='Field "'+f.label+'" wajib diisi.';
      err.style.display='block';
      document.getElementById(f.id).focus();
      return;
    }
  }
  const cvFile=document.getElementById('daftar-cv').files[0];
  if(!cvFile){
    err.textContent='CV wajib diupload.';
    err.style.display='block';
    return;
  }
  if(!document.getElementById('daftar-consent').checked){
    err.textContent='Harap centang persetujuan penggunaan data.';
    err.style.display='block';
    return;
  }

  // Validasi NIK 16 digit
  const nikVal=document.getElementById('daftar-nik').value.trim();
  if(!/^\d{16}$/.test(nikVal)){
    err.textContent='NIK harus terdiri dari 16 digit angka.';
    err.style.display='block';
    document.getElementById('daftar-nik').focus();
    return;
  }

  loading.style.display='block';
  document.querySelector('#page-daftar button.btn-block').disabled=true;

  try{
    // Cek duplikat NIK / email
    const emailVal=document.getElementById('daftar-email').value.trim();
    try{
      const dup=await sbFetch('pelamar?or=(nik.eq.'+encodeURIComponent(nikVal)+',email.eq.'+encodeURIComponent(emailVal)+')&select=nama,status&limit=1');
      if(dup&&dup.length){
        const d=dup[0];
        const stTeks={menunggu:'sedang menunggu review',disetujui:'sudah disetujui dan dalam proses seleksi',ditolak:'sudah pernah mendaftar sebelumnya'}[d.status]||d.status;
        err.textContent='NIK atau email ini sudah terdaftar atas nama "'+d.nama+'" dan '+stTeks+'. Hubungi HR jika ada kesalahan.';
        err.style.display='block';
        loading.style.display='none';
        document.querySelector('#page-daftar button.btn-block').disabled=false;
        return;
      }
    }catch(dupErr){ /* lanjut meski cek duplikat gagal */ }
    const nama=document.getElementById('daftar-nama').value.trim();
    const ts=Date.now();
    const safeName=nama.replace(/[^a-zA-Z0-9]/g,'_');

    // Upload CV
    const cvExt=cvFile.name.split('.').pop();
    const cvPath=`cv/${safeName}_${ts}.${cvExt}`;
    const cvUrl=await uploadFile(cvFile, cvPath);

    // Upload portfolio (optional)
    let portfolioUrl=null;
    const portFile=document.getElementById('daftar-portfolio').files[0];
    if(portFile){
      const portExt=portFile.name.split('.').pop();
      const portPath=`portfolio/${safeName}_${ts}.${portExt}`;
      portfolioUrl=await uploadFile(portFile, portPath);
    }

    // Simpan ke Supabase
    const ipkVal=document.getElementById('daftar-ipk').value;
    const payload={
      nama,
      email:document.getElementById('daftar-email').value.trim(),
      no_hp:document.getElementById('daftar-hp').value.trim(),
      tempat_lahir:document.getElementById('daftar-tempat-lahir').value.trim(),
      tanggal_lahir:document.getElementById('daftar-tanggal-lahir').value,
      jenis_kelamin:document.getElementById('daftar-jk').value,
      alamat:document.getElementById('daftar-alamat').value.trim(),
      pendidikan_terakhir:document.getElementById('daftar-pendidikan').value,
      nama_institusi:document.getElementById('daftar-institusi').value.trim(),
      jurusan:document.getElementById('daftar-jurusan').value.trim(),
      tahun_lulus:parseInt(document.getElementById('daftar-tahun-lulus').value),
      ipk:ipkVal?parseFloat(ipkVal):null,
      posisi_dilamar:document.getElementById('daftar-posisi').value.trim(),
      jenis_rekrutmen:document.getElementById('daftar-jenis').value,
      pengalaman_kerja:document.getElementById('daftar-pengalaman').value.trim()||null,
      motivasi:document.getElementById('daftar-motivasi').value.trim(),
      nik:document.getElementById('daftar-nik').value.trim(),
      source:document.getElementById('daftar-source').value,
      lokasi_penempatan:document.getElementById('daftar-lokasi').value.trim(),
      cv_url:cvUrl,
      portfolio_url:portfolioUrl,
      status:'menunggu'
    };

    await sbFetch('pelamar', {method:'POST', body:JSON.stringify(payload)});
    showPage('page-daftar-sukses');
  }catch(e){
    err.textContent='Gagal mengirim lamaran: '+e.message;
    err.style.display='block';
  }finally{
    loading.style.display='none';
    const btn=document.querySelector('#page-daftar button.btn-block');
    if(btn) btn.disabled=false;
  }
}

// ===== LOAD PELAMAR =====
async function loadPelamar(){
  const status=document.getElementById('filter-status-pelamar')?.value||'';
  const cari=document.getElementById('filter-cari-pelamar')?.value.toLowerCase()||'';
  const tbody=document.getElementById('tabel-pelamar');
  if(tbody) tbody.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:28px;font-size:.85em">⏳ Memuat data...</td></tr>';
  try{
    let url='pelamar?order=dibuat_at.desc';
    if(status) url+=`&status=eq.${status}`;
    const data=await sbFetch(url);
    allPelamarData = data || []; // cache untuk lowongan count
    const filtered=(data||[]).filter(p=>
      !cari||(p.nama||'').toLowerCase().includes(cari)||(p.posisi_dilamar||'').toLowerCase().includes(cari)
    );
    const tbody=document.getElementById('tabel-pelamar');
    if(!filtered.length){
      tbody.innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:24px">Belum ada pelamar.</td></tr>';
      return;
    }
    tbody.innerHTML=filtered.map(p=>{
      const tgl=new Date(p.dibuat_at).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
      const statusBadge={menunggu:'<span style="background:#fff3cd;color:#856404;padding:3px 10px;border-radius:20px;font-size:.78em;font-weight:600">⏳ Menunggu</span>',
        disetujui:'<span style="background:#d4edda;color:#155724;padding:3px 10px;border-radius:20px;font-size:.78em;font-weight:600">✅ Disetujui</span>',
        ditolak:'<span style="background:#f8d7da;color:#721c24;padding:3px 10px;border-radius:20px;font-size:.78em;font-weight:600">❌ Ditolak</span>'}[p.status]||p.status;
      const chatBtn = `<button class="btn btn-sm btn-ghost" onclick="bukaModalChat('${p.id}','${esc(p.nama)}','${esc(p.posisi_dilamar)}')" title="Chat dengan kandidat" style="padding:5px 8px">💬</button>`;
      const hapusBtn=`<button class="btn btn-sm btn-danger" onclick="hapusPelamar('${p.id}','${esc(p.nama)}')" title="Hapus pelamar" style="padding:5px 8px">🗑️</button>`;
      const aksi=p.status==='menunggu'
        ?`<button class="btn btn-sm" onclick="approvePelamar('${p.id}')" style="background:var(--green)">✓ Approve</button>
           <button class="btn btn-sm btn-ghost" onclick="lihatDetailPelamar('${p.id}')">Detail</button>
           <button class="btn btn-sm btn-danger" onclick="tolakPelamar('${p.id}')">Tolak</button>${chatBtn}${hapusBtn}`
        :p.status==='disetujui'
        ?`<button class="btn btn-sm btn-ghost" onclick="lihatDetailPelamar('${p.id}')">Detail</button>${chatBtn}${hapusBtn}`
        :`<button class="btn btn-sm btn-ghost" onclick="lihatDetailPelamar('${p.id}')">Detail</button>${chatBtn}${hapusBtn}`;
      return `<tr>
        <td><strong>${p.nama}</strong></td>
        <td style="font-size:.82em">${p.email}</td>
        <td>${p.posisi_dilamar}</td>
        <td><span class="badge badge-${p.jenis_rekrutmen==='karyawan'?'fulltime':p.jenis_rekrutmen||'fulltime'}">${{magang:'Magang',fulltime:'Karyawan FT',parttime:'Karyawan PT',karyawan:'Karyawan FT'}[p.jenis_rekrutmen]||p.jenis_rekrutmen}</span></td>
        <td style="font-size:.82em">${tgl}</td>
        <td>${statusBadge}</td>
        <td style="display:flex;gap:4px;flex-wrap:wrap">${aksi}</td>
      </tr>`;
    }).join('');
  }catch(e){
    document.getElementById('tabel-pelamar').innerHTML='<tr><td colspan="7" style="text-align:center;color:var(--danger)">Gagal memuat data pelamar.</td></tr>';
  }
}

