// Build flat viaItems array in interleaved order (round-robin)
// Round 1: +1 of each, Round 2: +2, Round 3: -1, Round 4: -2
const viaItems = [];
for (let round = 0; round < 4; round++) {
  for (let s = 0; s < 24; s++) {
    const sItems = viaStrengthItems[s];
    const [text, dir] = sItems[round];
    viaItems.push({
      id: `via_${s}_${round}`,
      strength: s, // index into viaStrengths
      text,
      dir // '+' or '-'
    });
  }
}
